def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    elephant_patches = image_patch.find("elephant")

    if len(elephant_patches) < 2:
        return image_patch

    elephant_patches.sort(key=lambda e: e.vertical_center)

    front_elephant = elephant_patches[-1]
    other_elephants = elephant_patches[:-1]

    for other in other_elephants:
        if front_elephant.overlaps_with(other.left, other.lower, other.right, other.upper):
            continue

        if front_elephant.compute_depth() < other.compute_depth():
            return front_elephant

    return front_elephant

