def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    lamb_patches = image_patch.find("lamb")
    if len(lamb_patches) < 2:
        return image_patch

    baby_lamb = min(lamb_patches, key=lambda l: l.width * l.height)
    mother_lamb = max(lamb_patches, key=lambda l: l.width * l.height)

    baby_lamb_center = (baby_lamb.left + baby_lamb.right) / 2
    mother_lamb_center = (mother_lamb.left + mother_lamb.right) / 2

    if abs(baby_lamb_center - mother_lamb_center) <= abs(baby_lamb.width / 2 + mother_lamb.width / 2):
        return baby_lamb
    else:
        return mother_lamb

