def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    giraffe_patches = image_patch.find("giraffe")

    if not giraffe_patches:
        return image_patch

    # Sort giraffes by their horizontal center to get the rearmost one
    giraffe_patches.sort(key=lambda g: g.horizontal_center)
    rear_giraffe = giraffe_patches[-1]

    # Find all giraffes in the foreground
    foreground_giraffes = [g for g in giraffe_patches if g != rear_giraffe and g.overlaps_with(rear_giraffe.left, rear_giraffe.lower, rear_giraffe.right, rear_giraffe.upper)]

    if not foreground_giraffes:
        return rear_giraffe

    # Check which part of the rear giraffe is partially blocked
    for fg_giraffe in foreground_giraffes:
        if fg_giraffe.overlaps_with(rear_giraffe.left, rear_giraffe.lower, rear_giraffe.right, rear_giraffe.upper):
            # Determine if the rear giraffe's rear end is partially blocked
            if fg_giraffe.horizontal_center < rear_giraffe.horizontal_center:
                return rear_giraffe

    return rear_giraffe

